let currentStep=1,formData={};const customAlertModal=document.getElementById("customAlertModal"),customAlertModalMessage=document.getElementById("customAlertModalMessage"),customAlertModalTitle=document.getElementById("customAlertModalTitle");function showCustomAlertModal(e,t='{% trans "Notification" %}'){customAlertModalTitle.textContent=t,customAlertModalMessage.textContent=e,customAlertModal.style.display="flex",setTimeout((()=>{customAlertModal.classList.add("show")}),10)}function hideCustomAlertModal(){customAlertModal.classList.remove("show"),setTimeout((()=>{customAlertModal.style.display="none"}),300)}function nextStep(e){validateStep(e)&&(saveStepData(e),showStep(e+1))}function previousStep(e){showStep(e-1)}function showStep(e){document.querySelectorAll(".step-container").forEach((e=>{e.style.display="none"}));const t=e<=3?`step-${e}`:4===e?"confirmation":"success",o=document.getElementById(t);o&&(o.style.display="block"),currentStep=e}function validateStep(e){let t=!0,o="";if(1===e){const e=document.getElementById("firstName").value.trim(),n=document.getElementById("lastName").value.trim(),a=document.getElementById("email").value.trim(),l=document.getElementById("phone").value.trim();e&&n&&a&&l?/^\S+@\S+\.\S+$/.test(a)||(t=!1,o='{% trans "Please enter a valid email address." %}'):(t=!1,o='{% trans "Please fill in all required personal information fields." %}')}else if(2===e){document.getElementById("cvFile").files[0]||(t=!1,o='{% trans "Please upload your CV file." %}')}else if(3===e){document.getElementById("motivationLetter").value.trim()||(t=!1,o='{% trans "Please write your motivation letter." %}')}return t||showCustomAlertModal(o,'{% trans "Validation Error" %}'),t}function saveStepData(e){1===e?(formData.first_name=document.getElementById("firstName").value.trim(),formData.last_name=document.getElementById("lastName").value.trim(),formData.email=document.getElementById("email").value.trim(),formData.phone=document.getElementById("phone").value.trim()):2===e?formData.cv_file=document.getElementById("cvFile").files[0]:3===e&&(formData.motivation_letter=document.getElementById("motivationLetter").value.trim())}function showConfirmation(){validateStep(3)&&(saveStepData(3),document.getElementById("confirm-firstName").textContent=formData.first_name,document.getElementById("confirm-lastName").textContent=formData.last_name,document.getElementById("confirm-email").textContent=formData.email,document.getElementById("confirm-phone").textContent=formData.phone,document.getElementById("confirm-cvFile").textContent=formData.cv_file?formData.cv_file.name:'{% trans "Not uploaded" %}',showStep(4))}function submitApplication(){const e=new FormData,t=document.querySelector("#step1-form [name=csrfmiddlewaretoken]")||document.querySelector("#step2-form [name=csrfmiddlewaretoken]")||document.querySelector("#step3-form [name=csrfmiddlewaretoken]");if(!t)return console.error("CSRF token not found!"),void showCustomAlertModal('{% trans "A security token is missing. Please refresh the page and try again." %}','{% trans "Error" %}');e.append("csrfmiddlewaretoken",t.value),e.append("first_name",formData.first_name),e.append("last_name",formData.last_name),e.append("email",formData.email),e.append("phone",formData.phone),formData.cv_file&&e.append("cv_file",formData.cv_file),e.append("motivation_letter",formData.motivation_letter);const o=document.querySelector(".btn-confirm"),n=o.innerHTML;o.disabled=!0,o.innerHTML='{% trans "Sending..." %}',fetch(window.location.href,{method:"POST",body:e}).then((e=>e.json())).then((e=>{e.success?showStep(5):showCustomAlertModal(e.message||'{% trans "An unknown error occurred. Please check your input." %}','{% trans "Application Error" %}')})).catch((e=>{console.error("Error:",e),showCustomAlertModal('{% trans "An error occurred while submitting your application. Please try again later." %}','{% trans "Submission Failed" %}')})).finally((()=>{o.disabled=!1,o.innerHTML=n}))}document.getElementById("cvFile").addEventListener("change",(function(e){const t=e.target.files[0]?e.target.files[0].name:'{% trans "Click to upload file" %}';document.getElementById("file-name").textContent=t})),customAlertModal.addEventListener("click",(function(e){e.target===customAlertModal&&hideCustomAlertModal()})),document.addEventListener("DOMContentLoaded",(function(){showStep(1)}));